#include <array>
#include <iostream>
#include <map>
int main() {
    const std::array<int, 6> data{2, 4, 2, 7, 2, 4};
    const std::array<int, 3> queries{2, 4, 7};
    int comparisons = 0, direct = 0;
    for (int key : queries) for (int value : data) {
        ++comparisons;
        direct += key == value;
    }
    std::map<int, int> counts;
    for (int value : data) ++counts[value];
    int indexed = 0;
    for (int key : queries) indexed += counts.at(key);
    if (indexed != direct) return 1;
    std::cout << "direct comparisons=" << comparisons << '\n';
    std::cout << "index visits=" << data.size() << " queries=" << queries.size()
              << " matches=" << indexed << '\n';
}

#include <iostream>
#include <string>
int main() {
    const std::string input = "0123456789";
    std::string batch, received;
    int calls = 0;
    const auto flush = [&] {
        if (batch.empty()) return;
        received += batch; // Model one sink call, preserving byte order.
        ++calls;
        batch.clear();
    };
    for (char item : input) {
        batch += item;
        if (batch.size() == 4) flush();
    }
    flush();
    if (received != input) return 1;
    std::cout << "per-item calls=" << input.size() << " batched calls=" << calls << '\n';
    std::cout << "received=" << received << '\n';
}
